package methodLabQuestion;

public class question11 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		checkEvenOdd(5);
	}
	public static void checkEvenOdd(int a)
	{
		if(a%2==0)
		{
			System.out.println("even");
		}
		else {
			System.out.println("odd");
		}
	}

}
